/* fb_cal.h — the calibration of the READ-ONLY PWM-feedback shadow
 * (app/fb_cal.c, GENERATED by tools/gen_fb_cal.py from the stock image).
 * Shadow-internal: only app/fb_shadow.c and the host tests include it. */
#ifndef TCU_APP_FB_CAL_H
#define TCU_APP_FB_CAL_H

#if defined(TCU_OUTPUT_PATH)
#error "the feedback shadow is read-only: an output path may not include fb_cal.h"
#endif

#include <stdint.h>

/* the capture configs 0x40954 (sub 0) / 0x40960 (sub 1) */
extern const uint32_t FB_CFG0_LIM[2], FB_CFG1_LIM[2];   /* +0 no-capture limit, +4 period limit */
extern const uint16_t FB_CFG0_GRBF[1], FB_CFG1_GRBF[1]; /* +8 GRBF reload */
extern const uint8_t  FB_CFG0_POL[1], FB_CFG1_POL[1];   /* +10 polarity */
extern const uint8_t  FB_PINS[15];                      /* 0x40D96 */
extern const uint16_t FB_IV_190210[3], FB_IV_1902D0[3]; /* sampler intervals, row 0 */
extern const uint16_t FB_PEXP[1];                       /* 0x191490 */
extern const uint16_t FB_M[1];                          /* 0x1916C4 */
extern const uint8_t  FB_HOLD[1];                       /* 0x1919F3 */
extern const int16_t  FB_COEF[10];                      /* 0x191294 */
extern const uint16_t FB_RFIX[10], FB_R20[10], FB_SPLIT[10], FB_KF[10], FB_KS[10];
extern const uint16_t FB_INOM[1], FB_KA[1];
extern const int16_t *const FB_C_A[10];                 /* 0x19103C.. diode drop vs board T */
extern const int16_t *const FB_C_B[10];                 /* 0x190FD8.. gain vs fluid T */
extern const int16_t *const FB_C_RDRV[10];              /* 0x191154.. driver R vs board T */
extern const int16_t *const FB_C_HEAT[10];              /* 0x191208.. self-heating vs fluid T */
extern const uint8_t  FB_DTBL_84A21[1];                 /* 0x65B31 */

/* the byte check (tests/unit/test_fb_cal.c) */
enum { FB_K_U8, FB_K_U16, FB_K_S16, FB_K_U32, FB_K_PTR };
typedef struct {
    uint32_t addr;          /* stock flash address */
    uint8_t  kind;
    uint32_t count;         /* elements; FB_K_PTR: the expected pointer value */
    const void *data;
} fb_cal_check_t;
extern const fb_cal_check_t FB_CAL_CHECKS[];
extern const unsigned FB_CAL_NCHECKS;

#endif /* TCU_APP_FB_CAL_H */
